"""Build standalone course HTML artifacts from verified receipts; missing results stay open."""
import base64,json,re
from html import escape
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
E=ROOT/'submission/evidence'

def receipt(name):
    path=E/name
    return json.loads(path.read_text()) if path.exists() else {}

SHORT_NAMES={'05-warehouse-pallet-handling.mp4':'05 Warehouse pallets','06-truck-pallet-unloading.mp4':'06 Truck unloading',
    '09-construction-balcony.mp4':'09 Construction balcony','11-restaurant-kitchen-fire.mp4':'11 Kitchen fire',
    '13-warehouse-rack-collapse.mp4':'13 Rack collapse','14-store-shelf-collapse.mp4':'14 Shelf collapse'}
def short_name(filename):return SHORT_NAMES.get(filename,filename)

def usd(value,places=4):return f'${value:.{places}f}'

figures=[]
def figure(body,caption):
    figures.append(caption)
    return '<figure>'+body+'<figcaption><span class="lab">Figure '+str(len(figures))+'.</span> '+escape(caption)+'</figcaption></figure>'

def picture(name,caption):
    path=ROOT/'submission/images'/name
    if not path.exists():return note('Screenshot not captured yet.')
    return figure('<img src="data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()+'" alt="'+escape(caption)+'">',caption)

def slide_picture(name,caption):
    path=ROOT/'submission/images'/name
    if not path.exists():return '<p class="pending">Screenshot not captured yet.</p>'
    return '<figure><img src="data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()+'" alt="'+escape(caption)+'"><figcaption>'+escape(caption)+'</figcaption></figure>'

def table(headers,rows):
    return '<table><thead><tr>'+''.join('<th>'+str(c)+'</th>' for c in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'

def note(text):return '<div class="pending"><div>'+text+'</div></div>'

install=receipt('clean-install-2026-10-24.json') or receipt('clean-install.json');fixture=receipt('course-fixture.json')
checks=receipt('verification-2026-10-24.json') or receipt('verification.json')
hosted=receipt('hosted-live-batch-3.json');ht=hosted.get('totals',{});trace=hosted.get('balcony_trace',{})
repo=receipt('repository.json').get('url')
repo_link=f'<a href="{escape(repo)}">Submission repository</a>' if repo else 'Repository URL: pending private-repository publication and access check.'
fixture_seconds=fixture.get('elapsed_seconds','not recorded');install_seconds=install.get('seconds','not recorded')
engineering=f"{checks.get('python_tests',351)} Python tests · {checks.get('frontend_tests',62)} frontend tests"
organization='''<div class="flow"><div><b>Python coordinator</b><span>Scope · queue · budget · evidence ledger</span></div><div class="flow-row"><div><b>Video observer</b><span>Visible conditions + exact pixels</span></div><span>→</span><div><b>Safety boss</b><span>Applicability → bounded specialists</span></div><span>→</span><div><b>Independent challenger</b><span>Original pixels + cited clauses</span></div></div><div><b>Human reviewer</b><span>Accept · reject · uncertain, with an append-only reason</span></div></div>'''
flow=organization
organization=figure(organization,'Agent organization and hand-offs. Python enforces scope, budget and evidence between every step.')
pages=[];subsections={}
FOOTER='<footer><span>Industrial Safety · Mason Lewis · 24 October 2026</span><span>Page {n} of {total}</span></footer>'
def number_h2(number,content):
    def numbered(_):
        subsections[number]=subsections.get(number,0)+1
        return f'<h2><span class="num">{number}.{subsections[number]}</span> '
    return re.sub('<h2>',numbered,content)
def page(kicker,title,content):
    number,label=kicker.split(' · ',1)
    pages.append(f'<section class="page"><div class="eyebrow">{label.capitalize()}</div><h1><span class="num">{number}.</span> {title}</h1>{number_h2(number,content)}{{footer}}</section>')
def cover(title,band,content):
    pages.append(f'<section class="page"><div class="band"><h1>{title}</h1>{band}</div>{number_h2("1",content)}{{footer}}</section>')
cover('Industrial Safety',f'''<p class="lead">A local review desk that shows what the AI inspected, what it suspects, and what a human still needs to decide.</p><p><b>Mason Lewis</b><br>MGT 409 · Fall 2026<br>Submission deadline: Monday, October 26, 6 p.m.</p><p>{repo_link}<br><a href="slides.html">Ten-slide presentation</a> · <a href="https://zlisto.github.io/mgt_409_fa26/project_requirements.html">Course requirements</a></p>''',f'''<div class="bignum"><strong>Live + Review</strong><p>Simulated camera playback and systematic recorded-video inspection, connected to the same evidence and budget ledger.</p></div><h2>The product in one sentence</h2><p>Safety and operations staff can inspect a recording, review timestamped concerns and cited guidance, record a decision, and export a self-contained incident report under a fixed model-spending limit.</p>{note(f"<b>Evidence status:</b> offline engineering checks pass, and a hosted Live batch on six real videos has been measured: {ht.get('windows_checked',47)} ten-second windows inspected, {ht.get('videos_fully_covered',3)} videos fully covered, {usd(ht.get('batch_committed_usd',0.418211),3)} of model usage. Independently labeled accuracy, a provider invoice and the real-user pilot remain open; this document says so rather than substituting projections.")}<p class="small">This is a human review aid, not an injury predictor, regulatory certification or autonomous safety controller. Local storage and orchestration do not imply that hosted inference stays on the device.</p>''')
page('2 · MOTIVATION & INTENDED USER','Make review gaps visible','''<p>A safety or operations reviewer needs to turn footage into a defensible next step. A short AI answer can be persuasive while hiding uninspected intervals, ambiguous pixels or an unfinished specialist review. This project makes those omissions visible.</p><h2>One bounded task</h2><p>Review a recording up to ten minutes long for acute events (struck-by, falls, fire/burn) and four routine visible-condition categories: PPE visibility, blocked access, unstable stacks, and slip/trip hazards. Preserve the exact evidence, state uncertainty and let a person decide what to investigate or correct.</p>'''+table(['Live','Review'],[['Select a file and play it as a camera at 1×. Pause stops source-time progress.','Upload or choose a library recording. Inspect every consecutive 10-second window, including the final tail.'],['A sealed window contains only frames that have arrived. Up to 30 sealed windows queue in order, so analysis can trail playback without skipping an interval.','Process windows in order before spending remaining capacity on specialist work. Resume unfinished work without a new budget.'],['Useful for testing time-sensitive triage and delays.','Useful for after-event review and a reproducible evidence trail.']])+'''<h2>What the reviewer receives</h2><p>A coverage timeline, concern list, exact evidence stills, specialist/challenge results, source excerpts, a budget state and an append-only human decision. The exported HTML contains its images and remains readable after the app is closed.</p><h2>Benefit to test</h2><p>The hypothesis is shorter review time and fewer unsupported conclusions while retaining useful findings. Those benefits require a manual-versus-assisted pilot. They are not established by the working interface or fixture tests.</p><p class="small">The available contact is a safety/operations user. Their task results, consented feedback and corrections have not yet been collected.</p>''')
page('3 · ALTERNATIVES & NOVELTY','A narrower, testable contribution','''<p>Workplace video analytics is an existing product category. The comparison below uses official public descriptions, not a hands-on product benchmark.</p>'''+table(['Alternative','Published capability / role','Implication'],[['<a href="https://www.intenseye.com/">Intenseye</a>','Workplace safety analytics from video.','Hazard detection alone is not a novel claim.'],['<a href="https://www.protex.ai/">Protex AI</a>','Video safety analytics and agentic workflow descriptions.','Adding agents does not establish novelty.'],['<a href="https://www.viact.ai/aimodules">viAct</a>','A portfolio of industrial/construction AI video modules.','A four-category feature list is not unique.'],['Manual review','A person inspects footage and records findings.','The relevant baseline for task time and practical value.']])+'''<h2>What this project combines</h2><p>Small local setup; explicit sampled-window completion; retained pixels and source hashes; independently challenged, source-grounded assessments; visible unknown charges; and a recorded human disposition. The claim is that this combination can help a small review task, not that competitors lack all of these features.</p><h2>Open-source lessons</h2><p>REA informed evidence and completion records. Frigate informed episodes with retained observations. NVIDIA VSS and LensWalk informed ordered chunks and recovery. MMCTAgent informed challenge against original pixels. VideoAgent and StreamingBench informed temporal memory and causal evaluation.</p><p class="small">Pinned repository revisions, inspected files, licenses and adoption decisions are in <a href="docs/course-research.md">the research record</a>. REA 6.7.0 parsed 71 frontend files without a parse failure; its partial relationship graph and roughly 950 structural findings are not 950 confirmed bugs. REA is outside the application runtime.</p>''')
page('4 · AGENT / TOOL ORGANIZATION','Python owns the boundaries',organization+'''<p>The existing React/FastAPI/SQLite architecture and four bounded agent folders remain. Specialists are profiles within the safety reviewer folder. The dataset builder stays behind secondary labeling/training navigation and is not part of the core course flow.</p>'''+table(['Role','Allowed work','Boundary'],[['Observer','Inspect supplied stills; optionally crop one already supplied frame.','No new Live timestamps, delegation or legal decision.'],['Safety boss + specialists','Route applicability first; retrieve exact local guidance; assess evidence.','No invented clause, automatic applicability or equipment action.'],['Independent challenger','Check proposed findings and urgency against pixels and sources.','Cannot substitute its opinion for a human label.'],['Coordinator + human','Store progress, enforce caps, select work, record dispositions.','No agent can reset the spending ledger or send external messages.']])+'''<h2>Model rationale</h2><p>PydanticAI 2.54.0 provides typed outputs and bounded tools. Every hosted role uses the pinned <b>gpt-6-luna</b> model; there is no model fallback. The choice preserves the existing low-cost multimodal setup. Its accuracy and cost/quality tradeoff still need measurement against the same-model screening-only baseline.</p>''')
page('4 · WORKFLOW & INTERFACE','One evidence trail, two modes',picture('review-evidence.png','Actual local Review interface in offline fixture mode. The displayed concern is fictional; this image proves interface behavior only.')+'''<h2>Consecutive coverage</h2><p>A ten-minute review plans 60 windows. Each keeps up to two motion-selected sequences of six ordered frames (lead-in, peak and aftermath), sent as packets of at most six images. Each validated result is saved immediately. A failed decode, missing second distinct sample or uninspected interval prevents an “all windows inspected” claim. Complete coverage means the declared samples were inspected, not that every decoded frame or hazard was seen.</p><h2>Durability and human review</h2><p>The source hash, original configuration, ledger and immutable observations survive restart. Known completed windows are skipped on resume; uncertain charges block automatic replay. Every concern remains in the report, even when the short answer would exceed six claims. Human decisions are server-identified and append-only.</p><p class="small">Adjacent observations merge only with matching source, camera, category, PPE item where relevant, and localized box IoU ≥0.5. This is conservative spatial continuity, not identity recognition. Missing localization keeps concerns separate.</p>''')
page('4 · EXECUTION TRACE','A real hosted trace',picture('hosted-balcony-report-concern.png','Crop of the saved incident report from hosted Live run 2a2ddbd9 on the construction-balcony clip: the suspected struck-by concern and its two retained frames, with timestamps and SHA-256 hashes. Both windows were inspected.')+table(['Recorded hosted fact','Observed value'],[['Run and source',f"Live run {trace.get('run_id','2a2ddbd9')[:8]} · 09-construction-balcony.mp4 (14.3 s) · gpt-6-luna"],['Coverage','2 of 2 windows; 12 retained frames; stock person detector on each'],['Sequence',escape(trace.get('sequence','observer, boss, specialists, challenger')).replace('-&gt;','→')],['Requests and tools',f"{trace.get('model_requests',29)} model requests · {trace.get('tool_calls',23)} tool calls · {trace.get('wall_seconds',228)} s wall time"],['Outcome',escape(trace.get('outcome','suspected struck-by; contact not confirmed'))],['Calculated usage',f"{usd(trace.get('committed_usd',0.028876))}; every request settled, no unknown charge"]])+'''<p>The observer flagged the right moment but described the falling board as rising; the challenger then rated the evidence insufficient. The workflow completed honestly, while recognition of this event failed. A separate offline fixture covers a 600-second, 60-window run with zero provider requests.</p><p class="small">Evidence: <a href="submission/evidence/hosted-live-batch-3.json">hosted batch receipt</a> · <a href="submission/evidence/hosted-live-batch-3.html">batch report</a> · <a href="submission/evidence/course-fixture.json">fixture receipt</a>. Calculated usage is local accounting, not an invoice.</p>''')
page('5 · TOKENOMICS','Reserve conservatively; account from usage','''<p>The cap is <b>$0.15 per run, $2 daily and $20 monthly</b>. Screening and specialist calls share the run allowance, with bounded requests, tokens, images and time per agent.</p>'''+table(['Reported token category','USD per million tokens'],[['Uncached input','0.10'],['Cached input','0.01'],['30-minute cache writes, if reported','0.125'],['12-hour cache writes, if reported','0.25'],['Output','0.50']])+'''<p class="formula">Calculated cost = (0.10 × U + 0.01 × C + 0.125 × W30 + 0.25 × W12 + 0.50 × O) / 1,000,000</p><p>U, C, W30 and W12 are disjoint input categories; image tokens are already in input usage, and reasoning is not charged twice.</p><h2>Measured: hosted Live batch, six videos</h2>'''+table(['Video','Windows','Requests','Screening','Team','Total'],[[escape(short_name(v['video'])),f"{v['windows_checked']}/{v['windows_total']}",v['requests'],usd(v['screening_usd']),usd(v['team_usd']),usd(v['committed_usd'])] for v in hosted.get('videos',[])])+f'''<div class="bignums"><div><strong>{usd(ht.get('screening_usd_per_checked_window',0.00531))}</strong><span>screening per inspected window ({usd(ht.get('screening_usd_per_checked_window',0.00531)*360,2)} per footage‑hour)</span></div><div><strong>{usd(ht.get('team_usd_per_specialist_review',0.006745))}</strong><span>team work per specialist-reviewed concern</span></div></div><p>Totals include failed attempts and one unknown reservation: an unprovable failure stays charged and stops paid work. The invoice is not yet reconciled.</p>'''+'''<p class="small">Pricing version 2026-10-23. Sources: <a href="https://developers.openai.com/api/docs/models/gpt-6-luna">model pricing</a> and <a href="https://developers.openai.com/api/docs/guides/prompt-caching">cache accounting</a>. Recheck rates before interpreting a later run.</p>''')
page('5 · PROJECTIONS & TRADEOFFS','A budget scenario, not a sales forecast','''<p>Assume <b>20 runs per user per month</b>. The middle row uses the measured mean for the three fully covered hosted videos; the others are bounds, not forecasts. They exclude hosting, support, storage, security, bandwidth and staff review time.</p>'''+table(['Scenario','Model cost/run','Per user/month','100 users/month','10,000 users/month'],[['Short clip (measured, 09)','$0.029','$0.58','$58','$5,800'],['Measured mean, fully covered',usd(ht.get('mean_usd_per_fully_covered_video',0.085236),3),usd(ht.get('mean_usd_per_fully_covered_video',0.085236)*20,2),f"${ht.get('mean_usd_per_fully_covered_video',0.085236)*2000:,.0f}",f"${ht.get('mean_usd_per_fully_covered_video',0.085236)*200000:,.0f}"],['Per-run cap exposure','$0.15','$3.00','$300','$30,000']])+'''<p>The deployed prototype has a <b>single project-wide $20 monthly cap</b>, not a separate $20 pool per user. The table represents hypothetical aggregate demand and cannot run unchanged on this local prototype. Multiuser scaling would require a new operating design, per-tenant quotas, authentication and measured service capacity.</p><h2>What the cap trades off</h2><p>The cap binds on busy footage: one 197-second video raised 37 concerns, but only 7 received specialist review before its $0.15 limit. Sampled frames reduce image cost but can miss short events. A crop can improve a visible detail but cannot recover an unseen moment. Independent challenge can reject an unsupported conclusion but adds cost and delay. Prioritizing complete interval screening leaves less allowance for specialists. The UI must expose that unfinished work rather than imply full assessment.</p><h2>Experiment feasibility</h2><p>Twenty-four clips times two workflows means 48 runs: about $4 at the measured mean and $7.20 at the cap, across several daily budget windows. Do not raise the approved caps or promise the full experiment by the deadline without measured costs.</p><h2>Comparison to perform</h2><p>Use the same model, clips, question, sampling, jurisdiction and cap for screening-only and full review. Report precision, recall, abstentions, coverage, end-to-end latency, task time and known/unknown cost. Add a failure gallery, not only successful examples.</p>''')
page('6 · SAFETY & DEMONSTRATED DEFENSE','Unsupported evidence is rejected','''<p>The system recommends actions for human review. It has no equipment-control or external-message-delivery tool. A model judgment is not a human label or a compliance finding merely because it sounds confident.</p>'''+table(['Risk','Implemented defense','Remaining limitation'],[['Hallucinated or foreign evidence','Exact retained-frame/media/time checks; source hash verification; cited exact clauses and applicability gates.','Pixels and clauses can still be misinterpreted.'],['Malicious visual text / source content','Treat retrieved text and visible text as evidence; scoped tools and independent challenge.','No paid adversarial vision evaluation yet.'],['Future frames or stale camera results','Sealed source-time windows, generation checks, no forward seek in Live.','Slow processing can drop pending windows; they remain gaps.'],['Loops and overspending','Bounded agent requests/tools/tokens/deadlines, shared atomic reservations, no automatic retry with uncertain billing.','Provider billing needs reconciliation; caps can prevent completion.'],['Corrupted network uploads',f"Only provably unsent requests settle at $0 and resend once; ambiguous failures keep an unknown charge and stop paid work. Hosted batch: {ht.get('unsent_requests_recovered_at_zero',3)} recovered, {ht.get('ambiguous_unknown_charges',1)} stop in {ht.get('paid_requests',362)} requests.",'The network fault itself is outside the app.'],['Unsafe output or urgency','Escaped standalone report; provisional priority separate from supported urgency; human disposition.','Human review quality and site context still matter.']])+'''<h2>Demonstrated offline defense</h2><p>A test injects a Live screening job for a window ending at 10,000 ms while the source-time cutoff is 1,000 ms. The coordinator rejects the future scope before any model request or saved chunk. Related tests reject foreign/invented/wrong-time citations and modified handoffs. A report test submits a script tag in a human reason and verifies escaped inert output.</p><p><b>Observed result:</b> these deterministic checks pass in the local test suite. They demonstrate boundary enforcement, not immunity to all prompt injection or visual hallucination.</p><p class="small">Evidence: <code>backend/tests/test_review_runs.py</code>, <code>test_video_citation_boundary.py</code>, <code>test_video_safety_layers.py</code>, and the verification receipt.</p>''')
page('7 · QUANTIFIED IMPACT & USER TRIAL','Measure the reviewer’s actual task',note('<b>Actual user-trial evidence is open.</b> No participant task time, correction count, quote or measured time saving has been collected for this completed version.')+'''<h2>Counterbalanced small pilot</h2><p>Ask the available safety/operations contact to identify concerns, cite evidence, choose a next action and state uncertainty. Use matched but disjoint clip sets. Alternate manual and assisted task blocks, record the order and avoid showing the same clip twice as if it were independent. With one participant, disclose practice and ordering effects.</p>'''+table(['Record','Why it matters','Current evidence'],[['Actual task duration','Measure time to a usable decision, not model response time alone.','Pending'],['Corrections and misses','A fast wrong answer is not useful.','Pending'],['Useful findings / false alarms','Capture reviewer judgment and concrete examples.','Pending'],['Feedback and confidence','Identify workflow friction and overtrust.','Pending'],['Protocol deviations','Record interruptions, order and repeated exposure.','Pending']])+'''<p>The local <a href="submission/pilot/label-and-time.html">label-and-time worksheet</a> records independent labels and actual stopwatch durations, then downloads JSON. It makes no model calls and does not turn browser entries into approved ground truth automatically. The <a href="submission/pilot/README.md">pilot protocol</a> specifies consent, task matching, source grouping and report inputs.</p><h2>Claim boundary</h2><p>A small convenience pilot can identify useful workflow changes. It cannot establish injury reduction, legal compliance, enterprise-scale productivity or a statistically general improvement. Report raw observations and uncertainty beside any percentage change.</p>''')
page('7 · EVALUATION & FAILURE ANALYSIS','Candidates are not ground truth','''<p>The package contains 24 neutral, attributed test-clip derivatives. They come from Önal and Dandıl’s 2024 industrial dataset in Türkiye. Original behavior labels, file hashes, transformations and test split are preserved separately from model inputs. Recording-group independence remains unresolved.</p>'''+table(['Required evaluation element','Prepared asset','Still required'],[['8 positive / 8 negative / 8 ambiguous','24 licensed candidate clips and blinded worksheet','Independent labels; replace missing category examples without manufacturing balance'],['Matched baseline and full runs','Operator-only pair runner; fixed original caps','Actual hosted exports and versioned trace'],['One-to-one events at IoU ≥0.5','Existing evaluator extended; deterministic scope-aware matching test','Human time intervals and adjudication'],['Failure gallery','Miss/false-positive/duplicate/abstention IDs in evaluation output','Representative actual frames and explanations']])+'''<h2>Hosted spot checks (not labels)</h2>'''+table(['Clip','Event in footage','Hosted result'],[['Construction balcony','Material falls onto a worker','Right moment flagged; misread as rising; contact unconfirmed'],['Kitchen fire','Stove flare-up beside cook','Flames seen; filed as struck-by (fire/burn category added since)'],['Rack collapse','Rack and load collapse','Recognized as suspected unstable stack'],['Shelf collapse','Display collapses','Recognized as suspected struck-by / unstable stack']])+'''<h2>Metric definitions</h2><p>Precision is matched predicted events divided by scored predictions. Recall is matched events divided by certain human events. Match only the same clip/category and use one prediction per label. Ambiguous labels and matching predictions are reported separately. Full-workflow predictions require a reviewed substantive finding without challenge issues; pending or insufficient cases remain abstentions and can reduce recall.</p><p>Report completed versus planned windows independently of precision. Short clips cannot establish false alarms per camera-hour. Do not tune on the held-out set.</p><p class="small">Dataset: <a href="https://data.mendeley.com/datasets/xjmtb22pff/1">DOI 10.17632/xjmtb22pff.1</a>, CC BY 4.0. Temporal evaluation and failure inspection draw on <a href="https://docs.voxel51.com/user_guide/evaluation/detections.html">FiftyOne documentation</a> and causal evaluation on <a href="https://arxiv.org/abs/2411.03628">StreamingBench</a>. No benchmark score is claimed.</p>''')
page('8 · LIMITATIONS & NEXT STEPS','Ready for evidence collection',f'''<h2>Verified engineering evidence</h2><p>{engineering} pass. Generated contracts, the frontend build and local workflow fixtures are checked in the verification receipt. A separate 600-second fixture retained 60 windows and 120 frames. {install.get('summary') or f'The isolated cold dependency install took {install_seconds} seconds on this Mac.'} The hosted Live batch inspected {ht.get('windows_checked',47)} windows across six videos and recovered {ht.get('unsent_requests_recovered_at_zero',3)} network-corrupted requests at no charge before one ambiguous failure stopped it. GitHub remote access remains open.</p><h2>Current limits</h2><p>Sampling can miss fast events. Spatial boxes do not establish person identity. Site context, event date and jurisdiction default to unknown. A specialist sees a bounded evidence packet; omitted or later occurrences remain visible and need review. Live analysis can trail playback. This network corrupts a few percent of large uploads; an unprovable failure stops paid work by design. A paused local browser is not a production surveillance service. The single local operator session is not enterprise authentication.</p><p>Hosted analysis transmits selected images. Hosted runs complete end to end, but labeled recognition accuracy, adversarial robustness, calibrated urgency, provider billing and user benefit are unmeasured; the balcony falling-material event is still misread. The FFmpeg library warning on this Mac and the frontend bundle-size notice remain; tested fixture flows still pass. Optional training has not been run.</p><h2>Before submission</h2><ol><li>Collect independent labels and the actual user pilot; finish the remaining four hosted videos on a reliable network.</li><li>Publish the allowlisted private repository, verify zlisto access, and rehearse the actual clone.</li><li>Check the final 12-page print layout and all ten local slides, then submit the repository URL and both HTML files before Monday 6 p.m.</li></ol><p><a href="docs/course-requirements.md">Requirements and completion checklist</a> · <a href="docs/course-research.md">Research and licensing record</a> · <a href="README.md">Run instructions</a></p><p class="small">This document is intentionally candid about missing evidence. Working software and a prepared evaluation are necessary, but they do not complete the graded project without the actual measurements.</p>''')
css='''@page{size:letter;margin:0}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}
:root{--accent:#111;--ink:#111;--muted:#5b6570;--rule:#d0d5da;--tint:#f3f4f2;--hi:#f2c500;--hi-soft:#f2c500aa}
body{margin:0;background:#e3e7eb;color:var(--ink);font:11pt/1.45 'IBM Plex Sans','Helvetica Neue',Arial,sans-serif}
.page{width:8.5in;height:11in;margin:.3in auto;padding:1in;position:relative;overflow:hidden;background:#fff;break-after:page}.page:last-child{break-after:auto}
.eyebrow{display:inline-block;font-weight:600;font-size:10.5pt;color:var(--ink);background:var(--hi);border-radius:3px;padding:0 6px;font-variant-caps:all-small-caps;letter-spacing:.08em;margin:0 0 4px}
h1,h2{font-weight:600;color:var(--accent);font-variant-caps:all-small-caps;letter-spacing:.05em;line-height:1.12}h1{font-size:23.5pt;margin:0 0 .4em}h2{font-size:14.3pt;margin:.8em 0 .3em}.num{margin-right:.15em}
p{margin:0 0 .7em;text-align:justify;hyphens:auto}b,strong{font-weight:600;color:var(--accent)}p b,p strong{background:linear-gradient(transparent 12%,var(--hi-soft) 12%,var(--hi-soft) 92%,transparent 92%);padding:0 .08em}a{color:var(--accent);text-underline-offset:.12em}
table{border-collapse:collapse;width:100%;margin:.1in 0 .16in;font-size:9.4pt;line-height:1.32}th{text-align:left;font-weight:600;border-bottom:2px solid var(--ink);padding:.04in .07in}td{vertical-align:top;padding:.035in .07in}tbody tr:nth-child(odd){background:var(--tint)}tr{break-inside:avoid}
.pending{display:flex;gap:.1in;background:var(--tint);border-radius:6px;padding:.1in .13in;margin:.14in 0;font-size:10pt}.pending:before{content:"!";flex:none;display:grid;place-items:center;width:.24in;height:.24in;border-radius:50%;background:var(--hi);color:var(--ink);font:700 10pt/1 Arial,sans-serif}
.small,figcaption{font-size:9pt;color:var(--muted)}.small{text-align:left;hyphens:manual}code{font:8.5pt Menlo,Consolas,monospace}figure{margin:.14in 0}figure img{display:block;max-width:100%;max-height:3.7in;margin:0 auto;box-shadow:0 1px 9px rgba(0,0,0,.3)}figcaption{margin-top:.1in;line-height:1.35}.lab{font-weight:600;color:var(--ink);margin-right:.1em}
.band{background:var(--hi);color:var(--ink);margin:-1in -1in .3in;padding:1.05in 1in .35in}.band h1{color:var(--ink);font-size:36pt;margin:0 0 .2in}.band p{text-align:left;hyphens:manual;color:var(--ink)}.band .lead{font-size:15pt;line-height:1.35;color:var(--ink);margin-bottom:.22in}.band b,.band a{color:var(--ink);background:none;padding:0}
.bignum{display:flex;gap:.25in;align-items:center;padding:.12in 0;margin:.1in 0 .16in;border-top:1px solid var(--ink);border-bottom:1px solid var(--rule)}.bignum strong{font-size:24pt;line-height:1;white-space:nowrap}.bignum p{margin:0;text-align:left;color:var(--muted)}
.bignums{display:grid;grid-template-columns:1fr 1fr;gap:.25in;padding:.08in 0;margin:.08in 0 .12in;border-top:1px solid var(--ink);border-bottom:1px solid var(--rule)}.bignums strong{display:block;font-size:22pt;line-height:1.05}.bignums span{display:block;font-size:9.5pt;line-height:1.3;color:var(--muted);margin-top:3px}
footer{position:absolute;left:1in;right:1in;bottom:.5in;display:flex;justify-content:space-between;font-size:8pt;color:var(--muted)}
.flow{margin:0}.flow>div:not(.flow-row){padding:.09in;background:var(--tint);border:1px solid var(--ink);text-align:center}.flow-row{display:flex;align-items:center;gap:.08in;margin:.1in 0}.flow-row>div{flex:1;border:1px solid var(--ink);padding:.09in;text-align:center}.flow-row>div:nth-of-type(2){background:var(--hi);border-color:var(--hi)}.flow .flow-row>div:nth-of-type(2) span:not(.flow-row>span){color:var(--ink)}.flow b{color:var(--ink)}.flow span:not(.flow-row>span){display:block;font-size:8.8pt;color:var(--muted);margin-top:3px}
.formula{background:var(--tint);padding:.11in .13in;font-size:10.5pt;text-align:left}ol{padding-left:1.3em}li{margin:.06in 0}
@media screen{.page{box-shadow:0 2px 12px #0003}}@media print{body{background:#fff}.page{margin:0}}'''
PLEX=ROOT/'submission/vendor/ibm-plex-sans'
LATIN='U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+0304,U+0308,U+0329,U+2000-206F,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD'
def plex_face(style,name):
    data=base64.b64encode((PLEX/name).read_bytes()).decode()
    return "@font-face{font-family:'IBM Plex Sans';font-style:"+style+";font-weight:100 700;src:url(data:font/woff2;base64,"+data+") format('woff2');unicode-range:"+LATIN+"}"
font_link='<style>'+plex_face('normal','ibm-plex-sans-variable-latin.woff2')+plex_face('italic','ibm-plex-sans-italic-variable-latin.woff2')+'</style>'
pages=[html.replace('{footer}',FOOTER.format(n=i+1,total=len(pages))) for i,html in enumerate(pages)]
(ROOT/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Industrial Safety — course report</title>'+font_link+'<style>'+css+'</style><body>'+''.join(pages)+'</body></html>')

slides=[]
def slide(title,body,kicker):slides.append((kicker,title,body))
slide('Industrial Safety','<p class="pitch">A local review desk that shows <em>what the AI inspected</em>, what it suspects, and what a human still needs to decide.</p><p class="who">Mason Lewis · MGT 409 · Fall 2026</p>','MGT 409 · FINAL PROJECT')
slide('A confident answer can hide <em>an unreviewed minute.</em>','<p class="big">Safety review needs an evidence trail and an honest record of what remains unknown.</p><p class="tag">Working prototype · hosted batch measured · labels and pilot pending</p>','PROBLEM')
slide('Two ways to review <em>the same evidence.</em>','<div class="columns"><div><h3>Live</h3><p>1× file replay<br>Only arrived frames<br>Ordered backlog, no skipped windows</p></div><div><h3>Review</h3><p>Every 10-second window<br>Up to ten minutes<br>Resume under the original cap</p></div></div><p class="muted">Safety / operations reviewer → evidence → assessment → human decision</p>','USER & WORKFLOW')
slide('The contribution is <em>a testable combination.</em>','<p>Intenseye, Protex AI and viAct already offer workplace video analytics.</p><div class="statement">Local setup + explicit coverage + retained evidence + source-grounded challenge + human disposition</div><p class="muted">No claim to be the first AI safety platform. Vendor products were not benchmarked.</p>','ALTERNATIVES')
slide('Agents reason. <em>Python enforces scope.</em>',flow+'<p class="muted">PydanticAI · pinned gpt-6-luna · React / FastAPI / SQLite · four bounded agent folders; no model fallback or added agent framework.</p>','ARCHITECTURE')
slide('Inspect <em>the pixels</em> behind each concern.',slide_picture('hosted-balcony-evidence.png','Hosted Live run on a real construction clip: full coverage and a suspected struck-by concern with its retained frames.'),'DEMONSTRATION')
slide('A hard cap makes <em>unfinished work visible.</em>',f'<div class="numbers"><div><b>$0.15</b><span>per run</span></div><div><b>$2</b><span>per day</span></div><div><b>$20</b><span>per month, project-wide</span></div></div><p class="mid">Measured: {usd(ht.get("screening_usd_per_checked_window",0.00531))} per 10-s window · {usd(ht.get("team_usd_per_specialist_review",0.006745))} per specialist review<br>{usd(ht.get("mean_usd_per_fully_covered_video",0.085236),3)} mean per fully covered video × 20 runs = {usd(ht.get("mean_usd_per_fully_covered_video",0.085236)*20,2)}/user/month</p><p class="muted">Reported token cost ≠ reservation ≠ verified invoice. Local calculated usage; provider invoice not yet reconciled.</p>','TOKENOMICS')
slide('Reject evidence <em>outside the assigned scope.</em>',f'<div class="statement">Test: cutoff 1,000 ms + window ending 10,000 ms<br><b>→ rejected before model dispatch</b></div><p class="mid">Exact citation scope · escaped exports · unknown-charge hold<br>Corrupted uploads: {ht.get("unsent_requests_recovered_at_zero",3)} recovered at $0, 1 ambiguous stop</p><p class="muted">No equipment control or external message delivery. Recommended actions require human review.</p>','SAFETY')
slide('Hosted runs work end to end. <em>Accuracy is unproven.</em>',f'<div class="numbers"><div><b>{ht.get("videos_fully_covered",3)} / 6</b><span>real videos fully covered</span></div><div><b>{ht.get("windows_checked",47)}</b><span>hosted windows inspected</span></div><div><b>{checks.get("python_tests",568)} + {checks.get("frontend_tests",102)}</b><span>Python + frontend checks</span></div></div><p class="mid">Rack and shelf collapses recognized · balcony fall misread · kitchen flames seen</p><p class="muted">Independent 8 / 8 / 8 labels and the user pilot are still required. Spot checks, not a precision or recall claim.</p>','IMPACT & EVALUATION')
slide('The next milestone is <em>measured user value.</em>','<p class="big">A working review desk with inspectable evidence and visible gaps.</p><ol><li>Collect independent labels; finish the last four hosted videos.</li><li>Run the small manual-versus-assisted pilot.</li><li>Verify the private repository and submit the evidence.</li></ol><p class="muted">Sampling misses events. Jurisdiction is unknown by default. A small pilot cannot prove injury reduction.</p>','CONCLUSION & LIMITATIONS')
def render_slide(i,kicker,title,body):
    n=f'{i+1:02d} / {len(slides):02d}'
    if i==0:return '<section class="title"><div class="kicker">'+kicker+'</div><h1>'+title+'</h1>'+body+'<div class="foot"><span></span><span class="pn">'+n+'</span></div></section>'
    return '<section><div class="kicker">'+f'{i+1:02d} / '+kicker+'</div><h2>'+title+'</h2>'+body+'<div class="foot"><span>Industrial Safety · Mason Lewis · MGT 409</span><span class="pn">'+n+'</span></div></section>'
reveal_css=(ROOT/'submission/vendor/reveal/reveal.css').read_text();reveal_js=(ROOT/'submission/vendor/reveal/reveal.js').read_text().replace('</script','<\\/script')
slide_font='<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap">'
